import { createContext, memo, useCallback, useContext, useEffect, useMemo, useState, type ReactNode } from 'react';
import type { Ticket } from '../types';

type TicketsContextValue = {
  tickets: Ticket[];
  selectedId: number | null;
  select: (id: number) => void;
  remove: (id: number) => void;
};

const TicketsContext = createContext<TicketsContextValue | null>(null);

export function TicketsProvider({ initial, children }: { initial: Ticket[]; children: ReactNode }) {
  const [tickets, setTickets] = useState(initial);
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [lastSync, setLastSync] = useState(() => new Date());

  useEffect(() => {
    const id = setInterval(() => setLastSync(new Date()), 10_000);
    return () => clearInterval(id);
  }, []);

  const select = useCallback((id: number) => setSelectedId(id), []);
  const remove = useCallback((id: number) => setTickets((list) => list.filter((t) => t.id !== id)), []);
  const value = useMemo(() => ({ tickets, selectedId, select, remove }), [tickets, selectedId, select, remove]);

  return (
    <TicketsContext value={value}>
      <small>Synchronizacja: {lastSync.toLocaleTimeString('pl-PL')}</small>
      {children}
    </TicketsContext>
  );
}

export function useTickets(): TicketsContextValue {
  const ctx = useContext(TicketsContext);
  if (!ctx) throw new Error('useTickets musi być użyty wewnątrz <TicketsProvider>');
