import { Profiler, useRef, type ProfilerOnRenderCallback } from 'react';
import { ProductList } from './ProductList';

type Sample = { id: string; phase: string; actualDuration: number; baseDuration: number };
type Product = { id: number; name: string; price: number };

export function MeasuredList({ products }: { products: Product[] }) {
  const samples = useRef<Sample[]>([]);

  const handleRender: ProfilerOnRenderCallback = (id, phase, actualDuration, baseDuration) => {
    samples.current.push({ id, phase, actualDuration, baseDuration });
  };

  function showStats() {
    const list = samples.current.filter((s) => s.phase !== 'mount');
    const total = list.reduce((sum, s) => sum + s.actualDuration, 0);
    console.table({
      commity: list.length,
      'suma ms': total.toFixed(1),
      'średnio ms': list.length ? (total / list.length).toFixed(2) : '—',
    });
  }

  return (
    <>
      <button type="button" onClick={showStats}>Pokaż statystyki</button>
      <Profiler id="products" onRender={handleRender}>
        <ProductList products={products} />
      </Profiler>
    </>
  );
}
